from pathlib import Path

app_path = Path('app.py')
nibo_path = Path('razync/nibo.py')
app = app_path.read_text(encoding='utf-8')
nibo = nibo_path.read_text(encoding='utf-8')

old_hist = '''def _historico(nome: str, descricao: str, referencia: str, identificacao: str) -> str:\n    nome = _limpar_nome(nome)\n    descricao = re.sub(r"\\s+", " ", str(descricao or "")).strip()\n    referencia = re.sub(r"\\s+", " ", str(referencia or "")).strip()\n    identificacao = re.sub(r"\\s+", " ", str(identificacao or "")).strip()\n\n    principal = " - ".join(parte for parte in (nome, descricao) if parte)\n    extras = [parte for parte in (referencia, identificacao) if parte]\n    if extras:\n        principal = " | ".join([principal] + extras) if principal else " | ".join(extras)\n    return principal or "MOVIMENTO NIBO"\n'''
new_hist = '''def _historico(nome: str, descricao: str, referencia: str = "", identificacao: str = "") -> str:\n    """Monta somente Nome + Descrição; Ref. e Identif. não vão para o Domínio."""\n    nome = _limpar_nome(nome)\n    descricao = re.sub(r"\\s+", " ", str(descricao or "")).strip()\n    principal = " - ".join(parte for parte in (nome, descricao) if parte)\n    return principal or "MOVIMENTO NIBO"\n'''
if old_hist not in nibo:
    raise SystemExit('Bloco _historico esperado não encontrado')
nibo = nibo.replace(old_hist, new_hist, 1)

old_row = '''            lancamentos.append({\n                "DESCRIÇÃO": "NIBO",\n                "DATA": data_formatada,\n                "VALOR": valor,\n                "DÉBITO": "",\n                "CRÉDITO": "",\n                "HISTÓRICO": _historico(nome, descricao, referencia, identificacao),\n                "PÁGINA": numero_pagina,\n            })\n'''
new_row = '''            historico_base = _historico(nome, descricao, referencia, identificacao)\n            prefixo_historico = "Pago:" if valor < 0 else "Recebido:"\n            lancamentos.append({\n                "DESCRIÇÃO": "NIBO",\n                "DATA": data_formatada,\n                "VALOR": valor,\n                "DÉBITO": "",\n                "CRÉDITO": "",\n                "HISTÓRICO": f"{prefixo_historico} {historico_base}",\n                "PÁGINA": numero_pagina,\n            })\n'''
if old_row not in nibo:
    raise SystemExit('Bloco de lançamento Nibo esperado não encontrado')
nibo = nibo.replace(old_row, new_row, 1)
nibo_path.write_text(nibo, encoding='utf-8')

old_ident = '''    if 'sicredi' in texto:\n        return 'sicredi'\n    return ''\n\ndef nome_banco_por_chave(chave):\n    return {\n        'itau': 'Itaú', 'bradesco': 'Bradesco', 'fibra': 'Fibra',\n        'daycoval': 'Daycoval', 'sicredi': 'Sicredi'\n    }.get(chave, chave)\n'''
new_ident = '''    if 'sicredi' in texto:\n        return 'sicredi'\n    if 'banco do brasil' in texto:\n        return 'banco_brasil'\n    return ''\n\ndef nome_banco_por_chave(chave):\n    return {\n        'itau': 'Itaú', 'bradesco': 'Bradesco', 'fibra': 'Fibra',\n        'daycoval': 'Daycoval', 'sicredi': 'Sicredi',\n        'banco_brasil': 'Banco do Brasil'\n    }.get(chave, chave)\n'''
if old_ident not in app:
    raise SystemExit('Identificador de bancos esperado não encontrado')
app = app.replace(old_ident, new_ident, 1)

old_fallback = '''                    'fibra': 'BANCO FIBRA', 'daycoval': 'BANCO DAYCOVAL',\n                    'sicredi': 'SICREDI'\n                }[banco_alvo]\n'''
new_fallback = '''                    'fibra': 'BANCO FIBRA', 'daycoval': 'BANCO DAYCOVAL',\n                    'sicredi': 'SICREDI', 'banco_brasil': 'BANCO DO BRASIL'\n                }[banco_alvo]\n'''
if old_fallback not in app:
    raise SystemExit('Fallback de descrição bancária esperado não encontrado')
app = app.replace(old_fallback, new_fallback, 1)

start_marker = "    # --- Ferramenta exclusiva 1529: Nibo -> Modelo Dominio ---\n"
end_marker = "# ==============================================================================\n# TELA 4: CONCILIAÇÃO COM O RAZÃO DA DOMÍNIO\n"
start = app.find(start_marker)
end = app.find(end_marker, start)
if start < 0 or end < 0:
    raise SystemExit('Bloco Nibo 1529 não encontrado')

new_block = '''    # --- Ferramenta exclusiva 1529: Nibo -> Modelo Dominio ---\n    if st.session_state['empresa_organizador'] == 'dias_pereira':\n        contas_dias_pereira = {'itau': '508', 'banco_brasil': '8'}\n        bancos_dias_pereira = {\n            'Itaú · Conta contábil 508': {\n                'slug': 'itau', 'descricao': 'BANCO ITAÚ', 'arquivo': 'Itau'\n            },\n            'Banco do Brasil · Conta contábil 8': {\n                'slug': 'banco_brasil', 'descricao': 'BANCO DO BRASIL', 'arquivo': 'Banco_do_Brasil'\n            },\n        }\n\n        aba_nibo, aba_base_dias = st.tabs([\n            'Organizar Nibo',\n            'Base inteligente de Débito e Crédito'\n        ])\n\n        with aba_base_dias:\n            renderizar_base_inteligente_empresa(\n                'dias_pereira',\n                '1529 - Dias e Pereira',\n                {'itau', 'banco_brasil'},\n                contas_dias_pereira\n            )\n\n        with aba_nibo:\n            st.markdown('### Nibo → Modelo Domínio')\n            st.caption(\n                'Selecione o banco e envie o PDF de Contas & Extratos exportado pelo Nibo. '\n                'O Razync organiza os movimentos e aplica a Base Inteligente exclusiva da 1529.'\n            )\n\n            banco_nibo_rotulo = st.selectbox(\n                'Banco deste relatório Nibo',\n                list(bancos_dias_pereira.keys()),\n                key='dias_pereira_banco_nibo'\n            )\n            config_banco_nibo = bancos_dias_pereira[banco_nibo_rotulo]\n\n            arquivo_nibo = st.file_uploader(\n                'Extrato Nibo em PDF',\n                type=['pdf'],\n                key='dias_pereira_extrato_nibo_pdf',\n                help='Use o relatório mensal de Contas & Extratos do Nibo.'\n            )\n\n            if arquivo_nibo is not None:\n                try:\n                    with st.spinner('Lendo e organizando o relatório Nibo...'):\n                        df_nibo = processar_extrato_nibo_pdf(arquivo_nibo.getvalue())\n\n                    df_export_nibo = df_nibo[\n                        ['DESCRIÇÃO', 'DATA', 'VALOR', 'DÉBITO', 'CRÉDITO', 'HISTÓRICO']\n                    ].copy()\n                    df_export_nibo['DESCRIÇÃO'] = config_banco_nibo['descricao']\n                    datas_nibo = pd.to_datetime(\n                        df_export_nibo['DATA'], dayfirst=True, errors='coerce'\n                    )\n                    entradas_nibo = df_export_nibo.loc[\n                        df_export_nibo['VALOR'] > 0, 'VALOR'\n                    ].sum()\n                    saidas_nibo = abs(df_export_nibo.loc[\n                        df_export_nibo['VALOR'] < 0, 'VALOR'\n                    ].sum())\n\n                    col_nibo_1, col_nibo_2, col_nibo_3 = st.columns(3)\n                    col_nibo_1.metric(\n                        'Lançamentos', f'{len(df_export_nibo):,}'.replace(',', '.')\n                    )\n                    col_nibo_2.metric(\n                        'Entradas',\n                        f'R$ {entradas_nibo:,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')\n                    )\n                    col_nibo_3.metric(\n                        'Saídas',\n                        f'R$ {saidas_nibo:,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')\n                    )\n\n                    st.success('Relatório Nibo organizado com sucesso.')\n                    st.dataframe(\n                        df_export_nibo[['DATA', 'VALOR', 'HISTÓRICO']],\n                        use_container_width=True,\n                        hide_index=True\n                    )\n\n                    excel_nibo = gerar_excel_modelo_dominio(df_export_nibo)\n                    datas_validas = datas_nibo.dropna()\n                    if not datas_validas.empty:\n                        nome_nibo = (\n                            f"1529_Dias_Pereira_{config_banco_nibo['arquivo']}_"\n                            f"{datas_validas.min().strftime('%m_%Y')}.xlsx"\n                        )\n                    else:\n                        nome_nibo = (\n                            f"1529_Dias_Pereira_{config_banco_nibo['arquivo']}_Modelo_Dominio.xlsx"\n                        )\n\n                    arquivo_saida_nibo = excel_nibo\n                    resumo_nibo = {}\n                    try:\n                        base_dias_pereira = carregar_classificacoes_online('dias_pereira')\n                        base_banco_nibo = [\n                            item for item in base_dias_pereira\n                            if item.get('banco') == config_banco_nibo['slug']\n                        ]\n                        arquivo_saida_nibo, resumo_nibo = classificar_planilha_final(\n                            excel_nibo,\n                            nome_nibo,\n                            base_banco_nibo,\n                            contas_dias_pereira\n                        )\n                    except Exception as erro_base_nibo:\n                        st.info(\n                            'O Modelo Domínio foi gerado normalmente, mas a Base Inteligente '\n                            f'não pôde ser aplicada agora: {erro_base_nibo}'\n                        )\n\n                    if resumo_nibo:\n                        c_auto_1, c_auto_2 = st.columns(2)\n                        c_auto_1.metric(\n                            'Classificados automaticamente',\n                            f"{int(resumo_nibo.get('automaticos', 0)):,}".replace(',', '.')\n                        )\n                        c_auto_2.metric(\n                            'Pendentes de contrapartida',\n                            f"{int(resumo_nibo.get('somente_banco', 0)):,}".replace(',', '.')\n                        )\n\n                    st.download_button(\n                        'Baixar Modelo Domínio',\n                        data=arquivo_saida_nibo,\n                        file_name=nome_nibo,\n                        mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',\n                        use_container_width=True,\n                        key='dias_pereira_download_modelo_dominio'\n                    )\n                except Exception as erro_nibo:\n                    st.error(f'Não foi possível processar o relatório Nibo: {erro_nibo}')\n\n'''
app = app[:start] + new_block + app[end:]
app_path.write_text(app, encoding='utf-8')
